fn hash_bytes(bytes: &[u8]) -> u64 {
    bytes.iter().fold(0xcbf29ce484222325, |h, b| {
        (h ^ u64::from(*b)).wrapping_mul(0x100000001b3)
    })
}
// Unchanged rows return the original include_str line. An override requires the
// fixture/index, exact complete input bytes, and the exact predecessor line.
pub fn line<'a>(fixture: &str, index: usize, source: &[u8], original: &'a str) -> &'a str {
    match TEXTS.binary_search_by(|e| (e.0, e.1).cmp(&(fixture, index))) {
        Ok(i) => {
            let delta = TEXTS[i];
            assert_eq!(
                hash_bytes(source),
                delta.2,
                "shortcut full-source key {fixture}:{index}"
            );
            assert_eq!(
                hash_bytes(original.as_bytes()),
                delta.3,
                "shortcut original oracle {fixture}:{index}"
            );
            delta.4
        }
        Err(_) => original,
    }
}
